insert into public.collections (id, name, short_name, tagline, description, featured_product_id, tint, accent, theme, sort_order)
select v.id, v.name, v.short_name, v.tagline, v.description, v.featured, v.tint, v.accent, v.theme, base.m + v.ord * 10
from (values
  ('attack-on-titan', 'Attack on Titan Laundry', 'Attack on Titan', 'Beyond the walls.', 'Levi, Eren, Mikasa, Armin and the Titans themselves. Ten designs from inside, and outside, the walls.', 'no-regrets', '#152a44', '#d8c7a6', 'aot', 1),
  ('bleach', 'Bleach Laundry', 'Bleach', 'Draw your blade.', 'Ichigo, Aizen, Byakuya, Kenpachi and the rest of the Soul Society. Ten designs with something to prove.', 'you-saw-what-i-allowed', '#1a2848', '#f0b08e', 'bleach', 2),
  ('demon-slayer', 'Demon Slayer Laundry', 'Demon Slayer', 'Set your heart ablaze.', 'Tanjiro, Nezuko, the Hashira and the demons they hunt. Ten breathing styles on oversized tees.', 'set-your-heart-ablaze', '#1f2546', '#f3a37c', 'demon', 3),
  ('naruto', 'Naruto Laundry', 'Naruto', 'Believe it.', 'Naruto, Kakashi, Itachi, Minato and Shisui. Six designs straight out of the Hidden Leaf.', 'believe-it', '#16304a', '#f4b46c', 'naruto', 4),
  ('one-punch-man', 'One Punch Man Laundry', 'One Punch Man', 'One punch is enough.', 'Saitama, Genos, Tatsumaki, King, Garou and Mumen Rider. Ten designs, zero effort required.', 'hold-still', '#14304a', '#f2d36e', 'opm', 5)
) as v (id, name, short_name, tagline, description, featured, tint, accent, theme, ord)
cross join (select coalesce(max(sort_order), 0) as m from public.collections) as base;

